function validate([nums]) {
  if (!Array.isArray(nums) || nums.length < 2 || nums.length > 30000) return 'nums needs 2 to 30000 values.';
  if (nums.some(v => !Number.isInteger(v) || v < -100000 || v > 100000)) return 'Each value is an integer between -100000 and 100000.';
  // Work out the best value exactly (same O(n) formula) to enforce the 32-bit guarantee.
  const n = nums.length;
  let total = 0, gain = 0, low = -Infinity, high = Infinity;
  for (let i = 0; i + 1 < n; i++) {
    const edge = Math.abs(nums[i] - nums[i + 1]);
    total += edge;
    gain = Math.max(gain, Math.abs(nums[0] - nums[i + 1]) - edge, Math.abs(nums[n - 1] - nums[i]) - edge);
    low = Math.max(low, Math.min(nums[i], nums[i + 1]));
    high = Math.min(high, Math.max(nums[i], nums[i + 1]));
  }
  if (total + Math.max(gain, 2 * (low - high)) > 2147483647) return 'The answer must fit in a 32-bit signed integer.';
  return null;
}

