function maxValueAfterReverse(nums) {
  const n = nums.length;
  let total = 0;
  let gain = 0;
  let largestLow = -Infinity;
  let smallestHigh = Infinity;

  for (let i = 0; i + 1 < n; i++) {
    const a = nums[i];
    const b = nums[i + 1];
    const edge = Math.abs(a - b);
    total += edge;
    gain = Math.max(gain, Math.abs(nums[0] - b) - edge);
    gain = Math.max(gain, Math.abs(nums[n - 1] - a) - edge);
    largestLow = Math.max(largestLow, Math.min(a, b));
    smallestHigh = Math.min(smallestHigh, Math.max(a, b));
  }
  gain = Math.max(gain, 2 * (largestLow - smallestHigh));
  return total + gain;
}

