function maxValueAfterReverse(nums) {
  const value = arr => {
    let sum = 0;
    for (let i = 1; i < arr.length; i++) sum += Math.abs(arr[i] - arr[i - 1]);
    return sum;
  };
  let best = value(nums);
  for (let left = 0; left < nums.length; left++) {
    for (let right = left + 1; right < nums.length; right++) {
      const copy = nums.slice(0, left).concat(nums.slice(left, right + 1).reverse(), nums.slice(right + 1));
      best = Math.max(best, value(copy));
    }
  }
  return best;
}

