function generate(rand, size) {
  if (size === 'large') {
    const nums = Array.from({ length: 2000 }, () => Math.floor(rand() * 200001) - 100000);
    return [nums];
  }
  const n = 2 + Math.floor(rand() * 8);
  const span = rand() < 0.5 ? 5 : rand() < 0.5 ? 50 : 100000;
  const nums = Array.from({ length: n }, () => Math.floor(rand() * (2 * span + 1)) - span);
  if (rand() < 0.2) nums.sort((x, y) => x - y);
  return [nums];
}
